var objTable;

$(document).ready(function( )
{
	$("#BtnAdd").button({ icons:{ primary:'ui-icon-plus' } });
	$(".btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false }).attr("disabled", true);


	objTable = $("#DataGrid").dataTable(   { sDom		 : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											 aoColumnDefs    : [ { bSortable:false, aTargets:[2] } ],
											 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											 aaSorting       : [ [ 0, "asc" ] ],
											 bJQueryUI       : true,
											 sPaginationType : "full_numbers",
											 bPaginate       : true,
											 bLengthChange   : false,
											 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											 bFilter         : true,
											 bSort           : true,
											 bInfo           : true,
											 bStateSave      : false,
											 bProcessing     : false,
											 bAutoWidth      : false
										   });



	$("#BtnSelectAll").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if (!$(objRows[i]).hasClass("selected"))
				$(objRows[i]).addClass("selected");
		}

		$("#BtnMultiDelete").show( );
	});


	$("#BtnSelectNone").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );
	});


	$(document).on("click", "#DataGrid tr", function( )
	{
		if ($(this).find("img.icnDelete").length == 0)
			return;


		if ($(this).hasClass("selected"))
			$(this).removeClass("selected");

		else
			$(this).addClass("selected");


		var bSelected = false;
		var objRows   = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				bSelected = true;

				break;
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );

		else
			$("#BtnMultiDelete").hide( );
	});


	$("#tabs-1 .TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
	$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
	$("#BtnMultiDelete").hide( );


	$(document).on("click", "#BtnMultiDelete", function( )
	{
		var sYears          = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sYears != "")
					sYears += ",";

				sYears += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sYears != "")
		{
			$("#ConfirmMultiDelete").dialog(   { resizable : false,
												 width     : 420,
												 height    : 110,
												 modal     : true,
												 buttons   : { "Delete" : function( )
																		   {
																				 $.post("ajax/payroll/delete-income-tax.php",
																					{ Years:sYears },

																					function (sResponse)
																					{
																						var sParams = sResponse.split("|-|");

																						showMessage("#GridMsg", sParams[0], sParams[1]);

																						if (sParams[0] == "success")
																						{
																						 for (var i = 0; i < objSelectedRows.length; i ++)
																							  objTable.fnDeleteRow(objSelectedRows[i]);

																						  $("#BtnMultiDelete").hide( );


																						  if ($("#SelectButtons").length == 1)
																						  {
																							if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																								$("#SelectButtons").show( );

																							else
																								$("#SelectButtons").hide( );
																						  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																 Cancel  : function( )
																		   {
																				$(this).dialog("close");
																		   }
															 }
											});
		}
	});


	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iYear  = this.id;
		var iIndex = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("payroll/edit-income-tax.php?Year=" + iYear + "&Index=" + iIndex), width:"800px", height:"500px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnView", function(event)
	{
		var iYear = this.id;

		$.colorbox({ href:("payroll/view-income-tax.php?Year=" + iYear), width:"750", height:"500px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var iYear  = this.id;
		var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog(   { resizable : false,
										width     : 420,
										height    : 110,
										modal     : true,
										buttons   : { "Delete" : function( )
																  {
																		$.post("ajax/payroll/delete-income-tax.php",
																			{ Years:iYear },

																			function (sResponse)
																			{
																				var sParams = sResponse.split("|-|");

																				showMessage("#GridMsg", sParams[0], sParams[1]);

																				if (sParams[0] == "success")
																					objTable.fnDeleteRow(objRow);


																				if ($("#SelectButtons").length == 1)
																				{
																					if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																						$("#SelectButtons").show( );

																					else
																						$("#SelectButtons").hide( );
																				}
																			},

																			"text");

																		$(this).dialog("close");
																  },

														Cancel  : function( )
																  {
																		$(this).dialog("close");
																  }
													}
									  });

		event.stopPropagation( );
	});



	$("#ddYear").change(function( )
	{
		if ($("#ddYear").val( ) == "")
			return;

		$.post("ajax/payroll/check-income-tax.php",
			{ Year:$("#ddYear").val( ) },

			function (sResponse)
			{
				if (sResponse == "USED")
				{
					showMessage("#RecordMsg", "info", "Income Tax of specified Year already exists in the System.");

					$("#DuplicateIncomeTax").val("1");
				}

				else
				{
					$("#RecordMsg").hide( );
					$("#DuplicateIncomeTax").val("0");
				}
			},

			"text");
	});


	$("#BtnAdd").click(function( )
	{
		var iIndex = ($("#IncomeTax .taxSlab").length + 1);

	     $.post("ajax/payroll/get-income-tax.php",
		    { Index:iIndex },

		    function (sResponse)
		    {
			  $("#IncomeTax").append(sResponse);

			  $("#txtMinimum" + iIndex).focus( );
			  $(".btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false });
			  $(".btnRemove").attr("disabled", false);
		    },

		    "text");

		return false;
	});


	$(document).on("click", ".btnRemove", function( )
	{
		var iIndex = this.id;

		$("#IncomeTax #TaxSlab" + iIndex).remove( );

		if ($("#IncomeTax .taxSlab").length == 1)
			$(".btnRemove").attr("disabled", true);


		$("#IncomeTax .taxSlab").each(function(iIndex)
		{
			$(this).attr("id", ("TaxSlab" + (iIndex + 1)));
			$(this).find(".minimum").attr("id", ("txtMinimum" + (iIndex + 1)));
			$(this).find(".maximum").attr("id", ("txtMaximum" + (iIndex + 1)));
			$(this).find(".percent").attr("id", ("txtPercent" + (iIndex + 1)));
			$(this).find(".fixed").attr("id", ("txtFixed" + (iIndex + 1)));
			$(this).find(".surchargeLimit").attr("id", ("txtSurchargeLimit" + (iIndex + 1)));
			$(this).find(".surchargeRate").attr("id", ("txtSurchargeRate" + (iIndex + 1)));
			$(this).find(".btnRemove").attr("id", (iIndex + 1));
		});

		return false;
	});

	$("#frmRecord #BtnReset").click(function( )
	{
		$("#IncomeTax .taxSlab").each(function(iIndex)
		{
			if (iIndex > 0)
				$("#IncomeTax #TaxSlab" + iIndex).remove( );
		});


		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		$("#frmRecord #ddYear").focus( );

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = false;


		if (!objFV.validate("ddYear", "B", "Please select the Year."))
			return false;

		$("#IncomeTax .taxSlab").each(function( )
		{
			var iIndex = this.id.replace("TaxSlab", "");

			if (!objFV.validate(("txtMinimum" + iIndex), "B,N", "Please enter the valid Minimum Amount."))
			{
				bFlag = true;

				return false;
			}

			if (!objFV.validate(("txtMaximum" + iIndex), "B,N", "Please enter the valid Maximum Amount."))
			{
				bFlag = true;

				return false;
			}

			if (!objFV.validate(("txtPercent" + iIndex), "B,F", "Please enter the valid Tax (%)."))
			{
				bFlag = true;

				return false;
			}

			if (!objFV.validate(("txtFixed" + iIndex), "B,N", "Please enter the valid Tax (Rs)."))
			{
				bFlag = true;

				return false;
			}

			if (!objFV.validate(("txtSurchargeLimit" + iIndex), "N", "Please enter the valid Surcharge Limit (Rs)."))
			{
				bFlag = true;

				return false;
			}

			if (!objFV.validate(("txtSurchargeRate" + iIndex), "B,F", "Please enter the valid Surcharge Rate (%)."))
			{
				bFlag = true;

				return false;
			}
		});

		if (bFlag == true)
			return false;

		if (objFV.value("DuplicateIncomeTax") == "1")
		{
			showMessage("#RecordMsg", "info", "Income Tax of specified Year already exists in the System.");

			objFV.focus("ddYear");

			return false;
		}


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});

