																									$("#SelectButtons").show( );

																								else
																									$("#SelectButtons").hide( );
																							  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																	 Cancel  : function( )
																			   {
																					$(this).dialog("close");
																			   }
													  }
											});
		}
	});


