	$("#frmRecord #ddPaymentMode").change(function( )
	{
		if ($(this).val( ) == "BT")
		{
			$("#BankAccount").show("blind");


			if ($("#ddEmployee").val( ) != "")
			{
				$.post("ajax/payroll/get-salary-bank-account.php", 
					{ Employee:$("#ddEmployee").val( ) },

					function (sResponse)
					{
						var sParams = sResponse.split("|-|");

						if (sParams[0] == "OK")
						{
							$("#ddBank").val(sParams[1]);
							$("#txtBranchCode").val(sParams[2]);
							$("#txtAccountNo").val(sParams[3]);
						}

					},

					"text");
			}
		}

		else if ($("#BankAccount").css("display") == "block")
		{
			$("#BankAccount").hide("blind");

			$("#ddBank").val("");
			$("#txtBranchCode").val("");
			$("#txtAccountNo").val("");
		}
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		clearList("#frmRecord #ddEmployee");

		$("#BankAccount").hide("blind");

		if ($("#frmRecord select#ddSchool").length > 0)
			$("#frmRecord #ddSchool").focus( );

		else
			$("#frmRecord #ddDepartment").focus( );

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddEmployee", "B", "Please select the Employee."))
			return false;

		if (!objFV.validate("txtGrossSalary", "B,N", "Please enter the Gross Salary."))
			return false;

		if (!objFV.validate("txtEffectiveDate", "B", "Please select the Effective Date."))
			return false;

		var objMinDate = parseDate($("#txtEffectiveDate").attr("date"));
		var objDate    = parseDate($("#txtEffectiveDate").val( ));

		if (objDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Effective Date (Old Dated entries are Restricted).");

			return false;
		}

		if (!objFV.validate("ddPaymentMode", "B", "Please select the Payment Mode."))
			return false;

		if (!objFV.validate("txtFuelAllowance", "N", "Please enter the Fuel Allowance."))
			return false;

		if (!objFV.validate("txtMobileAllowance", "N", "Please enter the Mobile Allowance."))
			return false;

		if (!objFV.validate("ddEobiApplicable", "B", "Please select whether EOBI is Applicable or not?."))
			return false;

		if (!objFV.validate("ddSsApplicable", "B", "Please select whether SS is Applicable or not?."))
			return false;

		if (objFV.value("ddPaymentMode") == "BT")
		{
			if (!objFV.validate("ddBank", "B", "Please select the Bank."))
				return false;

			if (!objFV.validate("txtBranchCode", "B", "Please enter the Branch Code."))
				return false;

			if (!objFV.validate("txtAccountNo", "B", "Please enter the Account No."))
				return false;
		}


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iSalaryId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Gross Salary")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Effective Date")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}


function updateSalaries( )
{
	objTable.fnDestroy( );	


	objTable = $("#DataGrid").dataTable(   { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											 aoColumnDefs    : [ { bSortable:false, aTargets:[6] } ],
											 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											 aaSorting       : [ [ 0, "desc" ] ],
											 bJQueryUI       : true,
											 sPaginationType : "full_numbers",
											 bPaginate       : true,
											 bLengthChange   : false,
											 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											 bFilter         : true,
											 bSort           : true,
											 bInfo           : true,
											 bStateSave      : false,
											 bProcessing     : false,
											 bAutoWidth      : false,
											 bServerSide     : true,
											 sAjaxSource     : "ajax/payroll/get-salaries.php",

											 fnServerData    : function (sSource, aoData, fnCallback)
															   {
																	if ($("div.toolbar #School").length > 0)
																		aoData.push({ name:"School", value:$("div.toolbar #School").val( ) });

																	if ($("div.toolbar #Department").length > 0)
																		aoData.push({ name:"Department", value:$("div.toolbar #Department").val( ) });

																	if ($("div.toolbar #PaymentMode").length > 0)
																		aoData.push({ name:"PaymentMode", value:$("div.toolbar #PaymentMode").val( ) });

																	if (sFromDate != "")
																		aoData.push({ name:"FromDate", value:sFromDate });

																	if (sToDate != "")
																		aoData.push({ name:"ToDate", value:sToDate });


																	$.getJSON(sSource, aoData, function(jsonData)
																	{
																		fnCallback(jsonData);


																		$("#DataGrid tbody tr").each(function(iIndex)
																		{
																			$(this).attr("id", $(this).find("img:first-child").attr("id"));
																			$(this).find("td:first-child").addClass("position");
																		});
																	});


																	if ($("#SelectButtons").length == 1)
																	{
																		if (objTable && objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																			$("#SelectButtons").show( );

																		else
																			$("#SelectButtons").hide( );
																	}
															   },

											 fnDrawCallback  : function( )
															   {
																   $(".details").tipTip( );
															   },

											 fnInitComplete  : function( )
															   {
																	$.post("ajax/payroll/get-salary-filters.php",
																		   {},

