																	var iDepartment = 0;

																	$("#DataGrid thead tr th").each(function(iIndex)
																	{
																		if ($(this).text( ) == "School")
																			iSchool = iIndex;

																		if ($(this).text( ) == "Department")
																			iDepartment = iIndex;
																	});

																	this.fnFilter("", iSchool);
																	this.fnFilter("", iDepartment);
															   }
											 } );	
}

