$(document).ready(function( )
{
	$("#frmReport #BtnExport, #frmReport #BtnView").button({ icons:{ primary:'ui-icon-disk' } });
	$("#frmReport #BtnReset").button({ icons:{ primary:'ui-icon-refresh' } });


	$("#frmReport #BtnReset").click(function( )
	{
		$("#frmReport")[0].reset( );
		$("#ReportMsg").hide( );

		$("#frmReport #ddReportType").trigger("change");

		return false;
	});


	$("#frmReport #ddReportType").change(function( )
	{
		if ($(this).val( ) == "bank-transfer-letter")
		{
			if ($("#BankAccount").css('display') == "none")
				$("#BankAccount").show("blind");
		}

		else
		{
			if ($("#BankAccount").css('display') == "block")
				$("#BankAccount").hide("blind");
		}


		if ($(this).val( ) == "payroll-sheet")
		{
			if ($("#PaymentMode").css('display') == "none")
				$("#PaymentMode").show("blind");
		}

		else
		{
			if ($("#PaymentMode").css('display') == "block")
				$("#PaymentMode").hide("blind");
		}


		if ($(this).val( ) == "employee-gl" || $(this).val( ) == "employee-pf" || $(this).val( ) == "salary-revisions")
		{
			if ($("#SingleSchool").css('display') == "none")
				$("#SingleSchool").show("blind");

			if ($("#ToMonthYear").css('display') == "none")
				$("#ToMonthYear").show("blind");

			if ($("#MultiSchools").css('display') == "block")
				$("#MultiSchools").hide("blind");

			$("#lblMonthYear").text("From Month/Year");
		}

		else
		{
			if ($("#SingleSchool").css('display') == "block")
				$("#SingleSchool").hide("blind");

			if ($("#ToMonthYear").css('display') == "block")
				$("#ToMonthYear").hide("blind");

			if ($("#MultiSchools").css('display') == "none")
				$("#MultiSchools").show("blind");

			$("#lblMonthYear").text("Month / Year");
		}


		if ($(this).val( ) == "employee-gl" || $(this).val( ) == "employee-pf")
		{
			if ($("#Employee").css('display') == "none")
				$("#Employee").show("blind");
		}

		else
		{
			if ($("#Employee").css('display') == "block")
				$("#Employee").hide("blind");
		}
	});


	$("#frmReport span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("#frmReport ." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});

		return false;
	});


	$("#frmReport #ddSchool, #frmReport #ddDepartment, #frmReport #ddStatus").change(function( )
	{
		getEmployeesList("#frmReport #ddSchool", "", "#frmReport #ddDepartment", "#frmReport #ddEmployee", "#frmReport #ddStatus");
	});


	$("#frmReport").submit(function( )
	{
		var objFV = new FormValidator("frmReport", "ReportMsg");
		var bFlag = false;

		if (!objFV.validate("ddReportType", "B", "Please select the Report Type."))
			return false;

		if (objFV.value("ddReportType") == "employee-gl" || objFV.value("ddReportType") == "employee-pf" || objFV.value("ddReportType") == "salary-revisions")
		{
			if (!objFV.validate("ddSchool", "B", "Please select the School."))
				return false;

			if (objFV.value("ddReportType") != "salary-revisions")
			{
				if (!objFV.validate("ddEmployee", "B", "Please select the Employee."))
					return false;
			}
		}

		else
		{
			$("#frmReport .school").each(function(iIndex)
			{
				if ($(this).prop("checked") == true)
					bFlag = true;
			});

			if (bFlag == false)
			{
				showMessage("#ReportMsg", "alert", "Please select at-least one School.");

				return false;
			}

			if (objFV.value("ddReportType") == "bank-transfer-letter")
			{
				if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
					return false;
			}
		}


		$("#BtnExport").attr('disabled', true);
		$("#ReportMsg").hide( );

		setTimeout(function( ) { $("#BtnExport").attr('disabled', false); }, 30000);
	});



	$(document).on("click", "#frmReport #BtnView", function(event)
	{
		var objFV = new FormValidator("frmReport", "ReportMsg");
		var bFlag = false;


		if (!objFV.validate("ddReportType", "B", "Please select the Report Type."))
			return false;

		if (objFV.value("ddReportType") == "employee-gl" || objFV.value("ddReportType") == "employee-pf" || objFV.value("ddReportType") == "salary-revisions")
		{
			if (!objFV.validate("ddSchool", "B", "Please select the School."))
				return false;

			if (objFV.value("ddReportType") != "salary-revisions")
			{
				if (!objFV.validate("ddEmployee", "B", "Please select the Employee."))
					return false;
			}
		}

		else
		{
			$("#frmReport .school").each(function(iIndex)
			{
				if ($(this).prop("checked") == true)
					bFlag = true;
			});

			if (bFlag == false)
			{
				showMessage("#ReportMsg", "alert", "Please select at-least one School.");

				return false;
			}

			if (objFV.value("ddReportType") == "bank-transfer-letter")
			{
				if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
					return false;
			}
		}


		$.colorbox({ href:("payroll/export-report.php?" + $("#frmReport").serialize() + "&Html=Y"), title:"[ <a href='javascript:window.frames[0].focus( ); window.frames[0].print( );'><b style='color:#ffffff;'>Print</b></a> ]", width:"99%", height:"99%", iframe:true, opacity:"0.50", overlayClose:false });


		return false;
	});
});
